mapper.select:
SELECT i.*, u.username FROM item i 
LEFT JOIN user u ON i.user_id = u.id 
WHERE 1=1

    AND i.type = #{type}


    AND i.status = #{status}


    AND i.category = #{category}


    AND (i.title LIKE CONCAT('%',#{keyword},'%') OR i.description LIKE CONCAT('%',#{keyword},'%') OR i.location LIKE CONCAT('%',#{keyword},'%'))


    AND i.user_id = #{userId}

ORDER BY i.create_time DESC
LIMIT #{offset}, #{size}

SELECT COUNT(*) FROM item i WHERE 1=1

    AND i.type = #{type}


    AND i.status = #{status}


    AND i.category = #{category}


    AND (i.title LIKE CONCAT('%',#{keyword},'%') OR i.description LIKE CONCAT('%',#{keyword},'%') OR i.location LIKE CONCAT('%',#{keyword},'%'))


    AND i.user_id = #{userId}
